# -*- coding: utf-8 -*-
T=[]
S="writing2"
T.append(dict(id="g2-ref",sec=S,day=9,task="Reference words and articles",before="Clinic · Reference words and articles: choose",
 emoji="👉",kicker="THE POINTING FINGER",title="This, Such, The:<br>Point Back Clearly",ch1="Point it out",
 hook="Welcome to the pointing finger. Good writing keeps pointing back at earlier ideas, so the reader never gets lost. Today you will learn to point with this, such and the, and to use articles correctly.",
 A="Fees rose. <b>This</b> hurts families.",B="Fees rose. <b>This increase</b> hurts families.",
 cmp="Look at these two sentences. Version A: fees rose. This hurts families. Version B: fees rose. This increase hurts families. Which finger points more clearly?",
 verdict="Version B points clearly. This alone could mean the fees, the problem, or the whole situation. Adding a noun, this increase, tells the reader exactly what you mean.",
 stampA="UNCLEAR",whyHead="Cohesion makes your post flow",whySub="Reference words connect sentences",why="Why does this matter? Raters look for sentences that connect. Reference words, used with a noun, link your ideas and make your post read as one argument.",
 rule=[
  dict(legend=["s:reference","v:noun"],sub="This + noun",rows=["s:This|v:increase|n:hurts families"],note="this trend · this effect · these measures",say="Use this or these with a noun to point back. Fees rose. This increase hurts families. Prices fell. This trend continues. The noun names exactly what you mean."),
  dict(sub="Such + noun",rows=["s:Such|v:measures|n:are costly"],note="such measures · such a policy",say="Such is another pointer. Such measures are costly. Such a policy is unfair. After such a, use a singular noun. After such, use a plural noun, with no a."),
  dict(sub="A first, the second",rows=["n:Schools adopted|s:a|n:rule.","s:The|n:rule is strict."],note="new → a / an · known → the",say="Articles also point. Use a or an for something new. Schools adopted a rule. Then use the for the same thing. The rule is strict. The article tells the reader whether it is new or known."),
  dict(sub="General ideas: no article",pair=["✗","<b>The</b> education is important.","✓","Education is important."],say="For general ideas, use no article. Education is important. Prices are rising. Use the only when you mean something specific: the education system in Bolivia."),
  dict(sub="Uncountable nouns",rows=["n:some|s:advice","n:a lot of|s:information"],note="advice · information · research · news",say="Uncountable nouns have no plural and no a. Some advice. A lot of information. Much research. When you point back to them, use this advice, this information.")],
 trap=dict(es="<b>La</b> educación es importante. · <b>Esto</b> afecta a las familias.",esnote="articles with general nouns · esto alone",say1="Now the trap. Spanish uses the article with general nouns: la educación es importante. And Spanish often points back with esto alone: esto afecta a las familias.",
  es2="<b>la</b> educación es importante",enbad="<b>the</b> education is important",say2="So Spanish speakers write: the education is important. Or: this hurts families, with no noun. In English, general ideas need no article, and this needs a noun.",
  stop="General? No article. This? Add a noun.",engood="Education is important. This <b>increase</b> hurts families.",say3="So, stop. For general ideas, remove the. And after this or such, add the noun that you mean.",
  more=[["Trap 2 · repeated a ✗","Schools adopted a rule. <b>A</b> rule is strict.","Fixed ✓","Schools adopted a rule. <b>The</b> rule is strict.","🔧","The second trap is repeating a. The second time you mention a noun, it is known, so use the. A rule, then the rule."]]),
 quiz=["Fees rose sharply. ___ increase hurts families.",["A","This","Some"],1],
 quizsay="Quick quiz. Fees rose sharply. Blank increase hurts families. Which word points back? ... The answer is B. This increase.",
 fix=dict(sub="Fix the sentence",row="g:The|v:Education|n:is important",say="Fix this one. The education is important. This is a general idea, so remove the. Education is important."),
 recap=["<b>this / such + noun</b> points back clearly","<b>a</b> for new · <b>the</b> for known","<b>No article</b> for general ideas"],
 recapsay="Three things to remember. One, use this or such with a noun to point back. Two, a for new things, and the for known things. Three, no article for general ideas.",
 done="Clear pointing!",donesay="Clear pointing! Your sentences now connect from start to finish. Go to the practice. Good luck!",
 check=dict(why1="This + noun points back clearly.",q2="Choose the correct sentence.",a2="Education is important.",w2=["The education is important.","An education is important.","Educations are important."],why2="General ideas need no article.")))
T.append(dict(id="g2-abs",sec=S,day=11,task="Abstract noun phrases",before="Clinic · Abstract noun phrases and nominalization: choose",
 emoji="🔭",kicker="ZOOM OUT",title="Turn Verbs<br>into Big Ideas",ch1="The telescope",
 hook="Welcome to the observatory. Academic writers zoom out: they turn actions into big abstract ideas. Instead of people are poorer, they say the growth of poverty. Today you will learn this powerful trick.",
 A="Technology <b>develops</b> quickly, and that worries me.",B="The <b>rapid development of</b> technology worries me.",
 cmp="Look at these two sentences. Version A: technology develops quickly, and that worries me. Version B: the rapid development of technology worries me. Both express the same idea, but at different zoom levels.",
 verdict="Version B zooms out. The verb develops became the noun development, and the whole idea became the subject of the sentence. It sounds more academic and more compact.",
 stampA="ZOOMED IN",stampB="ZOOMED OUT",whyHead="Sound academic, stay clear",whySub="Abstract questions need abstract phrases",why="Why does this matter? Abstract questions about fairness, progress or responsibility need abstract language. Noun phrases let you discuss ideas, not just events.",
 rule=[
  dict(legend=["v:verb / adjective","s:noun"],sub="Verb to noun",rows=["v:develop|v:→|s:development"],note="grow → growth · decide → decision · fair → fairness",say="Here is the trick. Change a verb or an adjective into a noun. Develop becomes development. Grow becomes growth. Decide becomes decision. Fair becomes fairness."),
  dict(sub="Noun + of",rows=["n:The|s:growth|n:of poverty|v:worries me"],note="The importance of · The rise of · The question of",say="Connect the noun with of. The growth of poverty worries me. The importance of honesty is clear. The question of responsibility is complex. The noun phrase is now the subject."),
  dict(sub="Add an adjective",rows=["n:The|q:rapid|s:development|n:of technology"],note="rapid · steady · global · ethical",say="Add an adjective for precision. The rapid development of technology. The steady decline of trust. A good adjective gives your idea a clear shape."),
  dict(sub="Right preposition",pair=["✗","The importance <b>for</b> honesty","✓","The importance <b>of</b> honesty"],say="Use the right preposition. The importance of honesty. The question of responsibility. The need for change. Check each noun, because the preposition depends on the word."),
  dict(sub="Not too many ofs",rows=["n:The growth of poverty|v:in cities"],note="Max two of's in one phrase",say="One warning. Do not stack too many of phrases. The development of the growth of the problem of poverty is heavy and unclear. One or two noun phrases per sentence is enough.")],
 trap=dict(es="<b>El desarrollo de</b> la tecnología preocupa.",esnote="Spanish forms these nouns easily",say1="Now the trap. In Spanish, these abstract nouns are natural: el desarrollo de la tecnología, la importancia de la honestidad. So you might think it is easy in English too.",
  es2="<b>la importancia de</b> la honestidad",enbad="the <b>importance for</b> honesty",say2="But Spanish speakers often choose the wrong preposition, writing importance for honesty. Or they use the wrong noun form: the develop of technology, or responsability with an a.",
  stop="Check the noun form and its preposition",engood="the <b>importance of</b> honesty · the <b>development of</b>…",say3="So, stop. Check two things: is it a noun, not a verb? And is the preposition the right one? Importance of, development of, need for.",
  more=[["Trap 2 · verb instead of noun ✗","The <b>develop</b> of technology is rapid.","Fixed ✓","The <b>development</b> of technology is rapid.","🔧","The second trap is the wrong form. After the, you need a noun: the development, not the develop."]]),
 quiz=["The ___ of poverty worries me.",["grow","growth","growing"],1],
 quizsay="Quick quiz. The blank of poverty worries me. After the, we need a noun. ... The answer is B. Growth. The noun form of grow.",
 fix=dict(sub="Fix the phrase",row="n:The|g:importance for|s:importance of|n:honesty is clear",say="Fix this one. The importance for honesty. The correct preposition is of. The importance of honesty is clear."),
 recap=["<b>Verb → noun</b>: develop → development","<b>Noun + of</b>: the growth of poverty","<b>Check</b> the preposition: importance of, need for"],
 recapsay="Three things to remember. One, turn the verb into a noun. Two, connect it with of, and add a precise adjective. Three, check the preposition after the noun.",
 done="Big ideas unlocked!",donesay="Big ideas unlocked! Your writing now zooms out like an academic. Go to the practice. Good luck!",
 check=dict(why1="After the, we need a noun.",q2="Choose the correct sentence.",a2="The importance of honesty is clear.",w2=["The importance for honesty is clear.","The important of honesty is clear.","The importance on honesty is clear."],why2="The right preposition is of.")))
T.append(dict(id="g2-hed",sec=S,day=12,task="Hedging",before="Clinic · Hedging with modals, passive and impersonal forms: choose",
 emoji="🎚️",kicker="THE DIMMER SWITCH",title="Turn Down<br>Your Claims",ch1="The dimmer",
 hook="Welcome to the dimmer switch. A claim can be bright and absolute, or soft and careful. In academic writing, you adjust the brightness to match your evidence. Today you will learn how to turn your claims up and down.",
 A="Studies <b>prove</b> that social media harms teenagers.",B="Studies <b>suggest</b> that social media <b>may</b> harm teenagers.",
 cmp="Look at these two claims. Version A: studies prove that social media harms teenagers. Version B: studies suggest that social media may harm teenagers. One claim is at full brightness, and the other is dimmed.",
 verdict="Version A is too bright. Prove is absolute, and it is rarely safe. Version B uses suggest and may, which match the real strength of the evidence. Academic readers trust careful claims.",
 stampA="TOO BRIGHT",stampB="JUST RIGHT",whyHead="Careful claims sound credible",whySub="Evidence and hedging are rated explicitly",why="Why does this matter? Raters reward claims that match the evidence. Overclaiming sounds naive, and invented statistics sound dishonest. Hedging shows judgment.",
 rule=[
  dict(legend=["s:bright","v:medium","q:dim"],sub="Three brightness levels",rows=["s:prove · always · everyone|v:suggest · tend to · often|q:may · might · sometimes"],say="Claims have three levels. Bright: prove, always, everyone. Medium: suggest, tend to, often. Dim: may, might, sometimes. Choose the level your evidence can support."),
  dict(sub="Modal verbs: may and might",rows=["n:Social media|v:may|n:harm teenagers"],note="may · might · could + base verb",say="Modal verbs dim a claim. Social media may harm teenagers. This policy might fail. Use may, might and could followed by the base verb, with no to."),
  dict(sub="Hedging verbs and phrases",rows=["v:tend to|v:appear to|v:seem to|v:is likely to"],note="Teenagers tend to sleep late.",say="Hedging verbs also work. Teenagers tend to sleep late. The policy appears to work. It seems to be effective. This policy is likely to fail."),
  dict(sub="Impersonal passives",rows=["n:It|aux:is argued|n:that|s:homework has limited value"],note="It is argued that · It is believed that · It is said that",say="Impersonal passives sound very academic. It is argued that homework has limited value. It is often said that technology isolates people. No named person is needed."),
  dict(sub="Never invent statistics",pair=["✗ risky","<b>87%</b> of students prefer…","✓ safe","<b>Most</b> students appear to prefer…"],say="One last rule. Do not invent exact numbers. If you do not know the statistic, use a general quantity: most, many, a majority. An invented number may be punished.")],
 trap=dict(es="<b>Está demostrado</b> que… · <b>Todo el mundo sabe</b> que…",esnote="Spanish accepts confident phrases",say1="Now the trap. Spanish accepts very confident phrases in academic writing: está demostrado que, todo el mundo sabe que. They sound normal and authoritative.",
  es2="<b>está demostrado</b> que…",enbad="it <b>is proven</b> that… · <b>everyone knows</b>…",say2="So Spanish speakers write: studies prove that, everyone knows that. In English academic writing, these sound absolute, and raters may see them as exaggeration.",
  stop="Match the claim to the evidence",engood="Studies <b>suggest</b> that… · It <b>is argued</b> that…",say3="So, stop. Before you write prove, ask: can I prove this? If not, use suggest, may, tend to, or an impersonal passive.",
  more=[["Trap 2 · tends ✗","Teenagers <b>tends</b> to spend time online.","Fixed ✓","Teenagers <b>tend</b> to spend time online.","🔧","The second trap is agreement. Teenagers is plural, so use tend, not tends. Tend to, with a plural subject."]]),
 quiz=["Studies ___ that sleep affects memory.",["prove","suggest","know"],1],
 quizsay="Quick quiz. Studies, blank, that sleep affects memory. Which verb is careful? ... The answer is B. Suggest. Studies suggest, not prove.",
 fix=dict(sub="Fix the claim",row="n:Studies|g:prove|v:suggest|n:that social media|v:may|n:harm teenagers",say="Fix this one. Studies prove that social media harms teenagers. Dim the claim: studies suggest that social media may harm teenagers."),
 recap=["<b>Dim</b> the claim: suggest, tend to, may","<b>It is argued that…</b> sounds academic","<b>Never invent</b> exact statistics"],
 recapsay="Three things to remember. One, dim the claim with suggest, tend to, or may. Two, use impersonal passives like it is argued that. Three, never invent exact statistics.",
 done="Perfect brightness!",donesay="Perfect brightness! Your claims now match your evidence. Go to the practice. Good luck!",
 check=dict(why1="Suggest is a hedged verb.",q2="Choose the correct sentence.",a2="Teenagers tend to spend more time online.",w2=["Teenagers tends to spend more time online.","Teenagers are tending to spend more time online.","Teenagers tending to spend more time online."],why2="Plural subject: tend.")))
T.append(dict(id="g2-err",sec=S,day=13,task="The top five errors",before="Clinic · The top five errors: choose",
 emoji="🔎",kicker="THE ERROR HUNT",title="Catch the Big Five",ch1="The hunt",
 hook="Welcome, hunter. In the last two minutes of a timed post, you cannot check everything. But five errors appear again and again. Today you will learn to hunt these five fast.",
 A="The students <b>is</b> tired. He gave me <b>an advice</b>.",B="The students <b>are</b> tired. He gave me <b>some advice</b>.",
 cmp="Look at these sentences. Version A: the students is tired. He gave me an advice. Version B: the students are tired. He gave me some advice. How many errors are hiding in Version A?",
 verdict="Two errors. The verb is does not agree with students, and advice cannot take an. These are two of the big five. Learn the list, and you can scan any post in under two minutes.",
 stampA="TWO ERRORS",whyHead="Two minutes, five checks",whySub="Edit for the errors that cost you most",why="Why does this matter? In a timed post, a small edit can change your accuracy score. If you know the big five, you can find most of the mistakes quickly.",
 rule=[
  dict(legend=["x:1","aux:2","s:3","v:4","q:5"],sub="The big five",rows=["x:agreement|aux:articles|s:tenses|v:run-ons|q:word forms"],say="Here are the big five. One, subject-verb agreement. Two, articles and uncountable nouns. Three, tenses. Four, run-ons and comma splices. Five, word forms. Check them in this order."),
  dict(sub="1 · Agreement",rows=["n:The students|v:are|n:tired"],note="Find each subject, then check its verb",say="Check one is agreement. Underline each subject and its verb. The students are tired. The number of students is growing. If the subject is plural, the verb is plural."),
  dict(sub="2 · Articles and uncountables",pair=["✗","He gave me an advice.","✓","He gave me some advice."],say="Check two is articles and uncountable nouns. Advice, information, research, news: no a, no plural. And general ideas take no article. Education is important."),
  dict(sub="3 · Tenses",pair=["✗","I have visited Sucre in 2019.","✓","I visited Sucre in 2019."],say="Check three is tenses. Is there a finished date? Then past simple. Is there since or for? Then present perfect. Make the verb match the time word."),
  dict(sub="4 and 5 · Run-ons and word forms",pair=["✗ run-on","I was late, I missed it.","✗ word form","It is very benefit."],say="Checks four and five. Look at every comma: does it join two sentences? And look after very, a and the: do you need a noun or an adjective? Beneficial, not benefit.")],
 trap=dict(es="Los estudiantes <b>están</b> cansados. · Me dio <b>un consejo</b>.",esnote="Spanish counts consejo and información differently",say1="Now the trap. Spanish grammar sometimes differs from English at exactly these points. In Spanish, consejo, advice, is countable: un consejo. And información has a plural: informaciones.",
  es2="me dio <b>un consejo</b>",enbad="he gave me <b>an advice</b>",say2="So Spanish speakers write: an advice, informations, researches. They look like normal plurals and articles, but English treats these nouns as uncountable.",
  stop="Check the big five, in order",engood="He gave me <b>some advice</b>.",say3="So, stop. Read your post once for each of the five checks. A slow read for agreement, then a slow read for articles, and so on.",
  more=[["Trap 2 · the run-on ✗","It rained<b>,</b> we stayed home.","Fixed ✓","It rained<b>, so</b> we stayed home.","🔧","The second trap is the run-on. A comma cannot join two sentences. Add so, but, or and, or use a semicolon."]]),
 quiz=["He gave me ___.",["an advice","some advice","advices"],1],
 quizsay="Quick quiz. He gave me, blank. Advice is uncountable. ... The answer is B. Some advice. No an, and no s.",
 fix=dict(sub="Fix the sentence",row="n:I was late|g:,|v:, so|n:I missed the bus",say="Fix this one. I was late, I missed the bus. Add so after the comma. I was late, so I missed the bus."),
 recap=["Check <b>agreement</b> and <b>articles</b> first","Check <b>tenses</b> against the time word","Check <b>commas</b> and <b>word forms</b> last"],
 recapsay="Three things to remember. One, check agreement and articles first. Two, check tenses against the time word. Three, check commas and word forms last.",
 done="Hunt complete!",donesay="Hunt complete! Five checks, two minutes, fewer errors. Go to the practice. Good luck, hunter!",
 check=dict(why1="Advice is uncountable.",q2="Choose the correct sentence.",a2="I was late, so I missed the bus.",w2=["I was late, I missed the bus.","I was late so, I missed the bus.","I was late, so, I missed the bus."],why2="A comma needs a conjunction.")))
T.append(dict(id="g2-part",sec=S,day=15,task="Participle and relative clauses",before="Clinic · Participle and relative clauses for combining ideas: choose",
 emoji="🗜️",kicker="THE COMPRESSOR",title="Squeeze Two Sentences<br>Into One",ch1="Compression",
 hook="Welcome to the compressor. Synthesis needs short, powerful sentences, and the best writers squeeze two ideas into one. Today you will learn two compression tools: participle clauses and reduced relative clauses.",
 A="The council reviewed the data. Then it changed its policy.",B="<b>Having reviewed</b> the data, the council changed its policy.",
 cmp="Look at these two versions. Version A: the council reviewed the data. Then it changed its policy. Version B: having reviewed the data, the council changed its policy. Same information, different compression.",
 verdict="Version B compresses two sentences into one. Having reviewed shows the first action, and the main clause shows the second. The subject, the council, belongs to both, so we write it once.",
 stampA="LOOSE",stampB="COMPRESSED",whyHead="Combine ideas smoothly",whySub="Synthesis posts need concise, connected language",why="Why does this matter? In a synthesis post you must combine several ideas in a few sentences. Compressed sentences keep your post short, and sound more advanced.",
 rule=[
  dict(legend=["s:action 1","v:action 2"],sub="Two actions, one subject",rows=["s:Having reviewed the data,|v:the council changed its policy"],note="having + past participle = earlier action",say="When the same subject does two actions, compress. Having reviewed the data, the council changed its policy. Having plus the past participle shows the earlier action."),
  dict(sub="-ing = active, at the same time",rows=["q:Feeling tired,|s:she|v:went to bed early"],note="Feeling tired, she went to bed.",say="An ing clause shows an action at the same time, or a reason. Feeling tired, she went to bed early. Walking home, I saw the rain start. Both parts share the same subject."),
  dict(sub="-ed = passive",rows=["n:Prices,|q:driven by inflation,|v:rose again"],note="driven · published · affected",say="An ed clause is passive. Prices, driven by inflation, rose again. The report, published in May, shows a rise. The ed form means the noun received the action."),
  dict(sub="Reduced relative clause",pair=["Full","Students <b>who live</b> far from campus often arrive late.","Reduced","Students <b>living</b> far from campus often arrive late."],say="You can also shorten a relative clause. Students who live far from campus becomes students living far from campus. Remove who and the helper, and keep the ing or ed form."),
  dict(sub="Same subject!",pair=["✗ dangling","Having reviewed the data, <b>the policy</b> changed.","✓","Having reviewed the data, <b>the council</b> changed the policy."],say="One serious rule. The subject of the clause and the subject of the main clause must be the same. Who reviewed the data? The council, not the policy.")],
 trap=dict(es="<b>Habiendo revisado</b> los datos, el consejo cambió…",esnote="Spanish gerunds are flexible",say1="Now the trap. Spanish uses the gerund and the perfect gerund flexibly: habiendo revisado los datos, el consejo cambió la política. It sounds natural.",
  es2="<b>habiendo revisado</b> los datos",enbad="<b>Having review</b> the data…",say2="So Spanish speakers sometimes write: having review the data, with no ed. Or they change the subject: having reviewed the data, the policy changed. English needs the participle form and the same subject.",
  stop="Same subject. Correct participle.",engood="<b>Having reviewed</b> the data, <b>the council</b> changed…",say3="So, stop. Check two things: is the verb in the past participle, and is the subject of both parts the same?",
  more=[["Trap 2 · wrong form ✗","The report, <b>publishing</b> in May, shows a rise.","Fixed ✓","The report, <b>published</b> in May, shows a rise.","🔧","The second trap is the wrong form. The report is published, so use the ed form. Not publishing."]]),
 quiz=["___ the data, the council changed its policy.",["Review","Having reviewed","Reviewed having"],1],
 quizsay="Quick quiz. Blank the data, the council changed its policy. The review came first. ... The answer is B. Having reviewed. A perfect participle.",
 fix=dict(sub="Fix the sentence",row="g:Having review|v:Having reviewed|n:the data, the council changed its policy",say="Fix this one. Having review the data. We need the past participle. Having reviewed the data, the council changed its policy."),
 recap=["<b>having + -ed</b>: the earlier action","<b>-ing</b> = active · <b>-ed</b> = passive","<b>Same subject</b> in both parts"],
 recapsay="Three things to remember. One, having plus the past participle shows the earlier action. Two, ing is active and ed is passive. Three, both parts must share the same subject.",
 done="Fully compressed!",donesay="Fully compressed! Your ideas now travel in tight, powerful sentences. Go to the practice. This is the last clinic, so make it count. Good luck!",
 check=dict(why1="Having + past participle shows the earlier action.",q2="Choose the correct sentence.",a2="Having reviewed the data, the council changed its policy.",w2=["Having review the data, the council changed its policy.","Have reviewed the data, the council changed its policy.","Having reviewing the data, the council changed its policy."],why2="Having + past participle.")))
